// Action
categoryApi.getList('?limit=5')
// Assertion
.then(response => {
  expect(response.status).to.eq(_categoryData.statusCodes.ok);
  expect(response.body).to.have.length(5);
  response.body.forEach(category => {
    expect(category).to.have.all.keys('id', 'name', 'slug', 'image', 'creationAt', 'updatedAt');
    expect(category.id).to.be.a('number');
    expect(category.name).to.be.a('string').and.not.be.empty;
    expect(category.image).to.match(/^https?:\/\//);
  });
});

