const name = (0, _categoryData.uniqueName)('QA API Read');
// Action
categoryApi.create((0, _categoryData.payloadFor)(name)).then(created => {
  expect(created.status).to.eq(_categoryData.statusCodes.created);
  const id = trackId(created.body.id);
  // Action lanjutan: baca ulang data yang baru dibuat
  return categoryApi.getById(id).then(fetched => {
    // Assertion
    expect(fetched.status).to.eq(_categoryData.statusCodes.ok);
    expect(fetched.body.id).to.eq(id);
    expect(fetched.body.name).to.eq(name);
  });
});

const initialName = (0, _categoryData.uniqueName)('QA API Update');
const updatedName = (0, _categoryData.uniqueName)('QA API Updated');
// Action
categoryApi.create((0, _categoryData.payloadFor)(initialName)).then(created => {
  expect(created.status).to.eq(_categoryData.statusCodes.created);
  const id = trackId(created.body.id);
  return categoryApi.update(id, {
    name: updatedName
  }).then(updated => {
    // Assertion
    expect(updated.status).to.eq(_categoryData.statusCodes.ok);
    expect(updated.body.id).to.eq(id);
    expect(updated.body.name).to.eq(updatedName);
    expect(updated.body.slug).to.eq((0, _categoryData.slugify)(updatedName));
    // Slug baru membuktikan perubahan benar-benar tersimpan
    expect(updated.body.slug).to.not.eq(created.body.slug);
  });
});

const name = (0, _categoryData.uniqueName)('QA API Delete');
// Action
categoryApi.create((0, _categoryData.payloadFor)(name)).then(created => {
  expect(created.status).to.eq(_categoryData.statusCodes.created);
  // Sengaja tidak di-track: test ini yang menghapus sendiri
  const id = created.body.id;
  return categoryApi.delete(id).then(deleted => {
    // Assertion: API mengembalikan teks "true" (bukan JSON boolean),
    // terlihat dari content-type: text/html. Dibandingkan sebagai string
    // sesuai perilaku nyata API.
    expect(deleted.status).to.eq(_categoryData.statusCodes.ok);
    expect(String(deleted.body)).to.eq(_categoryData.deleteSuccessBody);
    return categoryApi.getByIdRaw(id).then(afterDelete => {
      expect(afterDelete.status).to.eq(_categoryData.statusCodes.badRequest);
      expect(afterDelete.body.name).to.eq(_categoryData.expectedErrors.notFound);
    });
  });
});

// Action
categoryApi.createRaw(_categoryData.invalidPayload)
// Assertion
.then(response => {
  expect(response.status).to.eq(_categoryData.statusCodes.badRequest);
  expect(response.body.message).to.be.an('array');
  expect(response.body.message).to.include(_categoryData.expectedErrors.nameEmpty);
  expect(response.body.error).to.eq('Bad Request');
  // Data tidak boleh terbuat: API tidak mengembalikan id
  expect(response.body).to.not.have.property('id');
});
